mapper.insert:
insert into crm_mcp_api_key (
    tenant_id, name, key_prefix, key_hash, bound_user_id, allowed_tools, enabled, expires_at,
    service_token_enc, create_by, create_time, update_by, update_time
) values (
    #{tenantId}, #{name}, #{keyPrefix}, #{keyHash}, #{boundUserId},
    CAST(NULLIF(TRIM(#{allowedTools}), '') AS jsonb), #{enabled},
    #{expiresAt}, #{serviceTokenEnc}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}
)

mapper.update:
update crm_mcp_api_key
set enabled = 0,
    update_by = #{updateBy},
    update_time = #{updateTime}
where id = #{id} and tenant_id = #{tenantId}

update crm_mcp_api_key
set service_token_enc = #{serviceTokenEnc},
    update_time = #{updateTime}
where id = #{id} and tenant_id = #{tenantId}
